const required = ['junction_id','vehicle_count','avg_speed','queue_length','lane_occupancy','waiting_time','traffic_flow','signal_state'];
const reading = typeof msg.payload === 'string' ? JSON.parse(msg.payload) : msg.payload;
const invalid = required.some(key => reading[key] === undefined) || reading.vehicle_count < 0 || reading.avg_speed < 0 || reading.queue_length < 0 || reading.lane_occupancy < 0 || reading.lane_occupancy > 100 || reading.waiting_time < 0 || reading.traffic_flow < 0;
if (invalid) { node.warn('Rejected invalid traffic reading'); return null; }
const score = (reading.avg_speed < 20 ? 1 : 0) + (reading.avg_speed < 10 ? 1 : 0) + (reading.avg_speed < 5 ? 1 : 0) + (reading.queue_length >= 20 ? 1 : 0) + (reading.queue_length >= 40 ? 1 : 0) + (reading.queue_length >= 60 ? 1 : 0) + (reading.lane_occupancy >= 50 ? 1 : 0) + (reading.lane_occupancy >= 70 ? 1 : 0) + (reading.lane_occupancy >= 85 ? 1 : 0) + (reading.waiting_time >= 45 ? 1 : 0) + (reading.waiting_time >= 90 ? 1 : 0) + (reading.waiting_time >= 150 ? 1 : 0);
const levels = ['NORMAL','MODERATE','HIGH','CRITICAL'];
reading.congestion = levels[Math.min(Math.floor(score / 3), 3)];
reading.congestion_score = score;
reading.status = reading.congestion === 'CRITICAL' ? 'CRITICAL' : reading.congestion === 'HIGH' ? 'WARNING' : 'OK';
reading.recommendation = reading.congestion === 'CRITICAL' ? 'Increase green duration' : reading.congestion === 'HIGH' ? 'Prepare additional green time' : 'Monitor current signal plan';
const analytics = { ...msg, payload: reading, topic: 'traffic.analytics' };
const user = env.get('DITTO_USER') || 'ditto';
const password = env.get('DITTO_PASSWORD') || 'ditto';
const thing = { attributes: { junction_id: reading.junction_id, type: 'traffic-junction' }, features: { state: { properties: reading } } };
const ditto = { ...msg, method: 'PUT', url: (env.get('DITTO_URL') || 'http://ditto:8080') + '/api/2/things/traffic:' + reading.junction_id, headers: { 'content-type': 'application/json', authorization: 'Basic ' + Buffer.from(user + ':' + password).toString('base64') }, payload: thing };
return [analytics, ditto, analytics];

const value = msg.payload;
msg.url = 'http://influxdb:8086/api/v2/write?org=traffic&bucket=traffic&precision=s';
msg.method = 'POST';
msg.headers = { Authorization: 'Token ' + (env.get('INFLUX_TOKEN') || 'traffic-demo-token'), 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = 'traffic,junction_id=' + value.junction_id + ' vehicle_count=' + value.vehicle_count + 'i,avg_speed=' + value.avg_speed + ',queue_length=' + value.queue_length + 'i,lane_occupancy=' + value.lane_occupancy + ',waiting_time=' + value.waiting_time + ',traffic_flow=' + value.traffic_flow + ',congestion_score=' + value.congestion_score + 'i';
return msg;

if (msg.payload.status === 'OK') return null;
msg.topic = 'traffic/alerts/' + msg.payload.junction_id;
msg.payload = { junction_id: msg.payload.junction_id, status: msg.payload.status, congestion: msg.payload.congestion, recommendation: msg.payload.recommendation };
return msg;
